{
  "name": "qrypt-aes-generator",
  "version": "1.0.0",
  "description": "Generate an AES-256 key using Qrypt quantum entropy",
  "type": "module",
  "main": "index.js",
  "scripts": {
    "start": "node index.js"
  }
}

import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";

try {
  if (process.loadEnvFile) {
    process.loadEnvFile();
  }
} catch {}

const token = process.env.QRYPT_API_KEY?.trim();
if (!token) {
  console.error("Error: QRYPT_API_KEY is not set.");
  process.exit(1);
}

const url = "https://api-eus.qrypt.com/api/v1/quantum-entropy?size=1";
const headers = {
  Accept: "application/json",
  Authorization: <REDACTED> ${token}`,
  "User-Agent": "qrypt-quickstart-node/1.0"
};

console.log("Fetching quantum entropy from Qrypt EUS...");
const res = await fetch(url, { headers, redirect: "manual" });

if (!res.ok) {
  const errText = await res.text();
  console.error(`Failed to fetch quantum entropy: ${res.status} ${res.statusText} - ${errText}`);
  process.exit(1);
}

const data = await res.json();
const rawEntropy = data.random?.[0];
if (!rawEntropy) {
  console.error("Error: Unexpected response format from Qrypt API:", data);
  process.exit(1);
}

const aesKey = Buffer.from(rawEntropy, "base64").subarray(0, 32);
console.log(`Generated AES-256 key (hex): ${aesKey.toString("hex")}`);

const iv = randomBytes(12);
const message = "Hello from Qrypt quantum entropy";
const cipher = createCipheriv("aes-256-gcm", aesKey, iv);
const ciphertext = Buffer.concat([cipher.update(message, "utf8"), cipher.final()]);
const decipher = createDecipheriv("aes-256-gcm", aesKey, iv).setAuthTag(cipher.getAuthTag());
const plaintext = Buffer.concat([decipher.update(ciphertext), decipher.final()]).toString();

console.log(`Decrypted message round-trip: "${plaintext}"`);
console.log("✔ Generated a 256-bit AES key from Qrypt quantum entropy (AES-GCM round trip OK).");

